#!/usr/bin/env python3
"""Generate Kotlin policy from reviewed JSON; no feed/code generators are run."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def render():
    p=json.loads((ROOT/'tools/event_policy.json').read_text())
    def strings(xs): return ',\n'.join('        '+json.dumps(x,ensure_ascii=False) for x in xs)
    return '''package kz.barajyq.app.data

import kz.barajyq.app.domain.EventCard

// GENERATED by tools/gen_event_policy.py from tools/event_policy.json.
// Roundups are not individual events. Never reject a named festival merely for its duration.
object EventContentPolicy {
    private val rejectedIds = setOf(
'''+strings(p['rejectedIds'])+'''
    )
    private val rejectedUrls = setOf(
'''+strings(p['rejectedUrls'])+'''
    )
    private val titlePatterns = listOf(
'''+strings(p['roundupTitlePatterns'])+'''
    ).map { Regex(it, RegexOption.IGNORE_CASE) }
    private val imageOnlyMarkers = listOf(
'''+strings(p['imageOnlyMarkers'])+'''
    )

    fun normalizePrice(value: String?): String? = value?.trim()?.takeUnless {
        it.isEmpty() || it.equals("null", ignoreCase = true) || it.equals("none", ignoreCase = true)
    }

    fun isAllowed(e: EventCard): Boolean {
        if (e.isPlace) return true
        if (e.id in rejectedIds || e.sourceUrl in rejectedUrls) return false
        val titles = listOf(e.titleRu, e.titleKk, e.titleEn,
            e.descriptionRu.lineSequence().firstOrNull { it.isNotBlank() }.orEmpty())
        if (titles.any { title ->
            val heading = title.trim().dropWhile { !it.isLetterOrDigit() }
            titlePatterns.any { it.containsMatchIn(heading) }
        }) return false
        return e.startsAt.isNotBlank() || imageOnlyMarkers.none { e.descriptionRu.lowercase().contains(it) }
    }

    fun clean(items: List<EventCard>): List<EventCard> = items.filter(::isAllowed)
        .map { it.copy(price = normalizePrice(it.price)) }
}
'''
if __name__=='__main__':
    (ROOT/'android/app/src/main/java/kz/barajyq/app/data/EventContentPolicy.kt').write_text(render())
